@startuml

class Song {
  + title : string
  + year : int
  + length : time
  + genre : string
}

class Artist {
  + name : string
  + dateOfBirth : date
  + websiteURL : string
}

class User {
  + userID : int
  + name : string
  + address : string
}

class RegularUser {
  + purchaseHistory : string
}

class BusinessUser {
  + VATNumber : string
}

class Single {}

class Hit {}

class Album {
  + title : string
}

class Track {
  + trackNumber : int
}

class Suggestion {
  + similarityScore : double
}

User "1" -- "0..*" RegularUser
User "1" -- "0..*" BusinessUser

RegularUser "1" -- "*" Single : buys
RegularUser "1" -- "*" Album : buys

BusinessUser "1" -- "*" Single : uploads
BusinessUser "1" -- "*" Hit : uploads

Hit "1" *-- "1" Track
Track "*" -- "1" Album

Album "1" -- "0..*" Suggestion
RegularUser "1" -- "0..*" Suggestion

Song "1" -- "1" Artist : belongsTo
Song "1" -- "1" Single : is
Song "1" -- "1" Hit : is

@enduml

